function generateUUID() {
  let d = new Date().getTime(); // Timestamp
  let d2 = ((typeof performance !== 'undefined') && performance.now && (performance.now() * 1000)) || 0; // High-res timestamp
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    let r = Math.random() * 16; // Random number between 0 and 16
    if (d > 0) { // Use timestamp until it's consumed
      r = (d + r) % 16 | 0;
      d = Math.floor(d / 16);
    } else { // Use high-res timestamp if available
      r = (d2 + r) % 16 | 0;
      d2 = Math.floor(d2 / 16);
    }
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}
function assignUUIDsToJsonLd(jsonLdObject) {
  // If the input is not an object or array, return it as is.
  if (typeof jsonLdObject !== 'object' || jsonLdObject === null) {
    return jsonLdObject;
  }

  // If it's an array, iterate over its elements and process each.
  if (Array.isArray(jsonLdObject)) {
    return jsonLdObject.map(item => assignUUIDsToJsonLd(item));
  }

  // If it's an object, process its properties.
  const processedObject = { ...jsonLdObject };

  // Check if the current object has an '@id' property.
  // If not, assign a new UUID.
  if (typeof processedObject['@id'] === 'undefined' || processedObject['@id'] === null || processedObject['@id'] === '') {
    processedObject['@id'] = generateUUID();
  }

  // Recursively process all other properties of the object.
  for (const key in processedObject) {
    if (Object.prototype.hasOwnProperty.call(processedObject, key)) {
      processedObject[key] = assignUUIDsToJsonLd(processedObject[key]);
    }
  }

  return processedObject;
}
