function generateDB(values){

  values = Array.isArray(values) ? values : [values]

  let newDB = {}

  for(let v of values){

    let record_type = v?.['@type']
    let record_id = v?.['@id']

    if(! record_type || !record_id){
      continue
    }

    newDB[record_type] = newDB?.[record_type] || {}
    newDB[record_type][record_id] = v

  }

  return newDB
}


function unflattenChildValue(value, db, max_depth=5, depth=0){

  // array
  if(Array.isArray(value)){
    return value.map(x => unflattenChildValue(x, db))
  }

  // If object 
  if(typeof value === 'object' && value !== null){

    let record_type = value?.['@type']
    let record_id = value?.['@id']

    value = db[record_type]?.[record_id] || value

    if(depth < max_depth){

      let keys = Object.keys(value)
      for(let k of keys){
        value[k] = unflattenChildValue(value[k], db)
      }
    }

  }

  return value


}


function unFlatten(value, values){

  // array
  if(Array.isArray(value)){
    return value.map(x => unFlatten(x, values))
  }

  let db = generateDB(values)

  // If object 
  if(typeof value === 'object' && value !== null){

    let keys = Object.keys(value)
